<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;

class DatabaseImportSeeder extends Seeder
{
    public function run(): void
    {
        $this->command->info('=== DatabaseImportSeeder ===');

        $base64 = '';
        $json = base64_decode($base64);
        $data = json_decode($json, true);

        if (!$data) {
            $this->command->error('Data haipatikani!');
            return;
        }

        // 1. REGIONS
        if (Schema::hasTable('regions') && isset($data['regions'])) {
            foreach ($data['regions'] as $region) {
                DB::table('regions')->updateOrInsert(
                    ['id' => $region['id']],
                    [
                        'name' => $region['name'],
                        'code' => $region['code'],
                        'status' => $region['status'] ?? 'active',
                        'created_at' => now(),
                        'updated_at' => now(),
                    ]
                );
            }
            $this->command->info('✅ Regions (' . count($data['regions']) . ')');
        }

        // 2. DISTRICTS
        if (Schema::hasTable('districts') && isset($data['districts'])) {
            foreach ($data['districts'] as $district) {
                DB::table('districts')->updateOrInsert(
                    ['id' => $district['id']],
                    [
                        'region_id' => $district['region_id'],
                        'name' => $district['name'],
                        'code' => $district['code'],
                        'status' => $district['status'] ?? 'active',
                        'created_at' => now(),
                        'updated_at' => now(),
                    ]
                );
            }
            $this->command->info('✅ Districts (' . count($data['districts']) . ')');
        }

        // 3. WARDS
        if (Schema::hasTable('wards') && isset($data['wards'])) {
            $chunks = array_chunk($data['wards'], 100);
            foreach ($chunks as $chunk) {
                foreach ($chunk as $ward) {
                    DB::table('wards')->updateOrInsert(
                        ['id' => $ward['id']],
                        [
                            'district_id' => $ward['district_id'],
                            'name' => $ward['name'],
                            'code' => $ward['code'],
                            'status' => $ward['status'] ?? 'active',
                            'created_at' => now(),
                            'updated_at' => now(),
                        ]
                    );
                }
            }
            $this->command->info('✅ Wards (' . count($data['wards']) . ')');
        }

        // 4. ORGANIZATIONS
        if (Schema::hasTable('organizations') && isset($data['organizations'])) {
            foreach ($data['organizations'] as $org) {
                DB::table('organizations')->updateOrInsert(
                    ['id' => $org['id']],
                    [
                        'name' => $org['name'],
                        'code' => $org['code'],
                        'created_at' => now(),
                        'updated_at' => now(),
                    ]
                );
            }
            $this->command->info('✅ Organizations (' . count($data['organizations']) . ')');
        }

        // 5. DEPARTMENTS — BILA is_active
        if (Schema::hasTable('departments') && isset($data['departments'])) {
            foreach ($data['departments'] as $dept) {
                DB::table('departments')->updateOrInsert(
                    ['id' => $dept['id']],
                    [
                        'name' => $dept['name'],
                        'code' => $dept['code'],
                        'created_at' => now(),
                        'updated_at' => now(),
                    ]
                );
            }
            $this->command->info('✅ Departments (' . count($data['departments']) . ')');
        }

        $this->command->info('✅ DatabaseImportSeeder imekamilika!');
    }
}